const randomItem = list => list[Math.floor(Math.random()*list.length)];
const randomGenderName = (country,gender='Non-binary') => {const names=genderFirstNames[country]?.[gender]||countryNamePools[country]?.first||personFirstNames;return randomItem(names);};
const defaultEthnicityForCountry = country => (middleEastCountries.some(c=>c.name===country)&&!['Cyprus','Turkey','Israel'].includes(country)?'Middle Eastern':({Nigeria:'Black',Ghana:'Black',Kenya:'Black','South Africa':'Black',Japan:'East Asian',China:'East Asian','South Korea':'East Asian',India:'South Asian',Brazil:'Latino',Mexico:'Latino',Philippines:'East Asian'}[country]||'White'));
const toneForEthnicity = ethnicity => ({White:'🏻','East Asian':'🏼','South Asian':'🏽',Latino:'🏽',Black:'🏿','Middle Eastern':'🏽',Mixed:'🏼',Indigenous:'🏽'}[ethnicity]||'🏼');
const avatarPresets = (gender,ethnicity) => {const tone=toneForEthnicity(ethnicity);const bases=gender==='Girl'?['👩','👩‍🦱','👩‍🦰','👩‍🦳']:gender==='Boy'?['👨','👨‍🦱','👨‍🦰','👨‍🦳']:['🧑','🧑‍🦱','🧑‍🦰','🧑‍🦳'];return bases.map(base=>base.replace(/^(👩|👨|🧑)/,`$1${tone}`));};
const makePerson = (role, age, extra={}, country='United States') => {const names=countryNamePools[country]||{first:personFirstNames,last:personLastNames};const gender=extra.gender||(role==='Parent'?randomItem(['Woman','Man']):randomItem(['Girl','Boy']));const id=`person-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;return npcFinancialProfile({id,avatarSeed:id,ethnicity:defaultEthnicityForCountry(country),sexualOrientation:Math.random()<.02?'Bisexual':Math.random()<.02?(gender==='Woman'||gender==='Girl'?'Lesbian':'Gay'):'Straight',name:`${randomGenderName(country,gender==='Woman'?'Girl':gender==='Man'?'Boy':gender)} ${extra.familyName||randomItem(names.last)}`,role,gender,age:Math.max(0,age),alive:true,closeness:role==='Parent'?82:role==='Sibling'?74:54,looks:35+Math.floor(Math.random()*66),health:75+Math.floor(Math.random()*26),personality:randomItem(['warm','curious','ambitious','funny','thoughtful','adventurous']),personalWealth:role==='Parent'?25000+Math.floor(Math.random()*275000):role==='Step-parent'?20000+Math.floor(Math.random()*230000):500+Math.floor(Math.random()*35000),generosityLevel:20+Math.floor(Math.random()*81),...extra},country);};
const createFamily = (age,country='United States') => {const pool=countryNamePools[country]||{last:personLastNames};const familyName=randomItem(pool.last);const parent=(relationshipLabel,gender,parentAge)=>makePerson('Parent',parentAge,{relationshipLabel,gender,familyName,maritalStatus:'married',estateValue:25000+Math.floor(Math.random()*175000),will:{status:'not-discussed',playerShare:.1}},country);return {parents:[parent('Mother','Woman',age+27),parent('Father','Man',age+30)],siblings:Array.from({length:1+Math.floor(Math.random()*2)},(_,i)=>makePerson('Sibling',Math.max(0,age+i-2),{gender:randomItem(['Girl','Boy']),familyName},country)),parentsTogether:true,stepParents:[],memorials:[]};};
const ageRelationshipsOneYear = game => {
  const agePerson = person => person.alive===false?person:npcFinancialProfile({ ...person, age:(person.age || 0)+1 },game.country);
  const family = game.family || createFamily(game.age || 0,game.country);
  return { family:{...family,parents:(family.parents||[]).map(agePerson),siblings:(family.siblings||[]).map(agePerson),stepParents:(family.stepParents||[]).map(agePerson)}, friends:(game.friends||[]).map(agePerson), partner:game.partner?agePerson(game.partner):null, children:(game.children||[]).map(agePerson), pets:(game.pets||[]).map(pet=>({...pet,age:(pet.age||0)+1,care:clamp((pet.care||75)-5),health:clamp((pet.health||90)-((pet.care||75)<35?5:1))})) };
};
