const fameCareers = new Set(['Professional Football Athlete','Professional Basketball Athlete','Professional Tennis Athlete','Professional Track Athlete','Screen Actor','Recording Musician','Professional Footballer','Professional Basketball Player','Film Director','Music Label Executive','Music Producer','Stand-up Comedian']);
