function generateLifeEvent(game, nextAge) {
  const recent = new Set((game.lifeEventHistory || []).slice(-8));
  let eligible = lifeEventDeck.filter(event => nextAge >= event.min && nextAge <= event.max && (!event.when || event.when(game)) && !recent.has(event.key));
  if (!eligible.length) eligible = lifeEventDeck.filter(event => nextAge >= event.min && nextAge <= event.max && (!event.when || event.when(game)));
  const event = eligible[Math.floor(Math.random() * eligible.length)] || lifeEventDeck[0];
  return { ...event, id:`${event.key}-${game.year+1}-${Math.random().toString(36).slice(2,7)}`, age:nextAge, companyId:(game.companies || [])[0]?.id || null };
}

const deathChanceForAge = age => age < 58 ? 0 : age < 68 ? .002 : age < 78 ? .008 : age < 88 ? .025 : age < 98 ? .065 : .14;
function generateFamilyEvent(game,nextAge) {
  const family=game.family||{parents:[],siblings:[],stepParents:[],memorials:[]};
  const parents=(family.parents||[]).filter(person=>person.alive!==false);
  const stepParents=(family.stepParents||[]).filter(person=>person.alive!==false);
  const aliveFriends=(game.friends||[]).filter(person=>person.alive!==false);
  const bereavement=(family.memorials||[]).filter(person=>game.year-(person.deathYear||game.year)<=3);
  const make=(event)=>({...event,id:`${event.key}-${game.year+1}-${Math.random().toString(36).slice(2,7)}`,age:nextAge});
  if(parents.length===2&&family.parentsTogether!==false&&Math.random()<.025) return make({key:'parents-divorce',category:'Family',icon:'💔',title:'Your parents are separating',text:'After a long time trying to work through their differences, your parents tell you they have decided to divorce. They both want to remain part of your life, but home may feel different for a while.',familyAction:'divorce',choices:[{label:'Tell them how this is affecting you',detail:'Ask for reassurance and a clear plan for staying connected.',result:'You spoke honestly about the upheaval. Your parents agreed to keep you informed and make time for you.',effects:{stats:{happiness:4}}},{label:'Stay close to both of them',detail:'Ask them to keep you out of the conflict.',result:'You reminded them that you love them both. They agreed not to put you in the middle of their divorce.',effects:{stats:{happiness:2,health:3}}},{label:'Take some space to process it',detail:'Let yourself adjust at your own pace.',result:'You took time to process the news privately. Your parents checked in and gave you room to adjust.',effects:{stats:{health:5}}}]});
  const divorced=parents.filter(person=>person.maritalStatus==='divorced'&&!stepParents.some(step=>step.parentId===person.id));
  if(divorced.length&&Math.random()<.055){const parent=randomItem(divorced);const names=countryNamePools[game.country]||{last:personLastNames};const newPartner=makePerson('Step-parent',Math.max(25,parent.age-2),{gender:Math.random()<.04?parent.gender:(['Woman','Girl'].includes(parent.gender)?'Man':'Woman'),familyName:randomItem(names.last),relationshipLabel:'Step-parent',closeness:35},game.country);return make({key:'parent-remarriage',category:'Family',icon:'💍',title:`${parent.name.split(' ')[0]} is thinking about remarriage`,text:`${parent.name} has been seeing someone for a while and tells you they are considering getting married. They want to know how you feel about welcoming ${newPartner.name.split(' ')[0]} into the family.`,familyAction:'remarriage',relativeId:parent.id,newPartner,choices:[{label:'Welcome them into the family',detail:'You are ready to give this new relationship a chance.',result:`You welcomed ${newPartner.name.split(' ')[0]} warmly. ${parent.name} felt supported as they began this next chapter.`,effects:{stats:{happiness:5}}},{label:'Ask for time to get to know them',detail:'Support your parent while setting a comfortable pace.',result:`You asked to get to know ${newPartner.name.split(' ')[0]} gradually. Your parent understood and made space for the three of you to spend time together.`,effects:{stats:{health:3}}},{label:'Share that this is difficult for you',detail:'Be honest that family changes bring up complicated feelings.',result:`You explained that the change is hard to process. ${parent.name} listened and promised you would still have a secure place in their life.`,effects:{stats:{happiness:2}}}]});}
  if(nextAge>=18&&parents.some(person=>person.will?.status!=='documented')&&Math.random()<.035){const parent=randomItem(parents.filter(person=>person.will?.status!=='documented'));return make({key:'family-estate-planning',category:'Family',icon:'📜',title:'A conversation about the future',text:`${parent.name} brings up estate planning and asks whether you have any questions about what might happen to the family’s home, savings, and keepsakes one day. It is a sensitive conversation, but a clear written will can spare the family confusion later.`,familyAction:'will-conversation',relativeId:parent.id,choices:[{label:'Encourage a written, fair will',detail:'Ask them to document their wishes and treat the children fairly.',result:`You had a thoughtful conversation with ${parent.name} about documenting their wishes.`,effects:{stats:{smarts:2,happiness:1}},willShare:'equal'},{label:'Ask them to remember you in their will',detail:'Explain what support would mean to you.',result:`You shared your hopes with ${parent.name} and asked them to consider your place in their will.`,effects:{stats:{happiness:1}},willShare:.25},{label:'Leave the decision private',detail:'Let them decide how they want their affairs handled.',result:`You told ${parent.name} that the decision was personal and left the details up to them.`,effects:{stats:{health:2}}}]});}
  const candidates=[...parents,...stepParents,...(family.siblings||[]),...aliveFriends,...(game.partner&&game.partner.alive!==false?[game.partner]:[])].filter(person=>person.alive!==false);
  for(const person of candidates){if(Math.random()<deathChanceForAge(person.age||0)){return make({key:`loss-${person.id}`,category:'Family & friends',icon:'🕯️',title:`A loss in your life: ${person.name}`,text:`You receive the heartbreaking news that ${person.name} has died${(person.age||0)>0?` at age ${person.age}`:''}. The people around you are making arrangements to remember them. You can attend the burial, help the family, or say goodbye privately.`,familyAction:'death',relativeId:person.id,choices:[{label:'Attend the burial',detail:'Be there with family and friends to say goodbye.',result:`You attended ${person.name}’s burial and shared stories with the people who loved them. The day was painful, but you were glad to be there.`,effects:{stats:{happiness:-4,health:2}},attendBurial:true},{label:'Help the family with arrangements',detail:'Offer practical support and attend the service.',result:`You helped the family with arrangements and attended the burial. Supporting one another gave everyone a little strength.`,effects:{stats:{happiness:-2,health:3}},attendBurial:true},{label:'Say goodbye in your own way',detail:'Choose a private farewell rather than attending.',result:`You said goodbye to ${person.name} privately. You grieved in your own way and remembered what they meant to you.`,effects:{stats:{happiness:-3,health:4}},attendBurial:false}]});}}
  if(bereavement.length&&Math.random()<.12){const lost=randomItem(bereavement);return make({key:`remember-${lost.id}-${nextAge}`,category:'Family & friends',icon:'🕯️',title:`A memory of ${lost.name}`,text:`A familiar song brings back memories of ${lost.name}. Grief still comes in waves, and you can decide whether to share the memory with someone or take a quiet moment for yourself.`,familyAction:'bereavement',choices:[{label:'Share a favorite story',detail:'Talk about them with someone who remembers them too.',result:`You shared a favorite memory of ${lost.name}. Remembering the good moments made the grief feel a little less lonely.`,effects:{stats:{happiness:5,health:2}}},{label:'Visit the grave or memorial',detail:'Spend time remembering them.',result:`You visited ${lost.name}’s memorial and left feeling a little more at peace.`,effects:{stats:{happiness:4,health:3}}},{label:'Take a quiet day',detail:'Give yourself space to feel what you feel.',result:`You gave yourself a quiet day to process the memory. You did not have to rush your grief.`,effects:{stats:{health:5}}}]});}
  return null;
}
function generateHousingEvent(game,nextAge){
  const home=game.livingArrangement;if(!home||home.mode!=='rent'||Math.random()>.16)return null;
  const landlord=home.landlord||'your landlord';const oldRent=Number(home.monthlyRent)||0;
  const options=[
    {key:'landlord-repair',title:'A repair request from the landlord',icon:'🪠',text:`A leak has started beneath the kitchen sink in your rented home. ${landlord} asks whether you can make time for the repair visit this week.`,choices:[{label:'Arrange access and document the repair',detail:'Cooperate and keep a record of the maintenance request.',result:`You coordinated the repair with ${landlord}. The leak was fixed and the tenancy stayed on good terms.`,effects:{stats:{happiness:2},housingRelationship:4}},{label:'Ask for a rent credit for the inconvenience',detail:'Request a modest one-time credit.',result:`${landlord} agreed to a small rent credit after the repair took longer than expected.`,effects:{money:Math.round(oldRent*.15),stats:{smarts:1},housingRelationship:2}},{label:'Ignore the messages',detail:'The repair may become a bigger problem.',result:'The repair was delayed. The landlord became less responsive and the issue remained a source of stress.',effects:{stats:{happiness:-4},housingRelationship:-8}}]},
    {key:'landlord-renewal',title:'Your lease is up for renewal',icon:'🔑',text:`${landlord} offers to renew your lease. Similar homes nearby are more expensive, but the proposed rent would still stretch your budget.`,choices:[{label:'Renew for another year',detail:`Keep your home; rent rises by 4% to ${moneyFmt(Math.round(oldRent*1.04))}/month.`,result:'You signed a one-year renewal and kept your home. The rent increase fits your budget for now.',effects:{stats:{happiness:2},housingRent:Math.round(oldRent*1.04)}},{label:'Negotiate the increase',detail:'Ask to renew at the current rate.',result:`You made a reasonable case and ${landlord} agreed to keep the rent unchanged this year.`,effects:{stats:{smarts:2},housingRelationship:5}},{label:'Decline and prepare to move',detail:'End the lease and return to your family home for now.',result:'You gave notice and moved out when the lease ended. Your family welcomed you back while you plan your next step.',effects:{stats:{happiness:-1},housingMoveOut:true}}]},
    {key:'landlord-neighbor',title:'A neighbor raises a noise concern',icon:'🔊',text:'A neighbor says late-night noise from your apartment has been disturbing them. Your landlord has passed along the complaint and asks you to respond.',choices:[{label:'Apologize and agree quiet hours',detail:'Keep the relationship with the neighbor and landlord calm.',result:'You apologized and agreed on quiet hours. The neighbor accepted, and the landlord closed the complaint.',effects:{stats:{happiness:1},housingRelationship:4}},{label:'Explain your side and suggest a compromise',detail:'Discuss a practical schedule for gatherings.',result:'You and the neighbor agreed on a compromise. The landlord appreciated the respectful response.',effects:{stats:{smarts:2},housingRelationship:2}},{label:'Dismiss the complaint',detail:'This could put your lease at risk.',result:'The complaint was escalated. Your landlord issued a formal warning under the lease.',effects:{stats:{happiness:-3},housingRelationship:-12}}]}
  ];
  const event=randomItem(options);return {...event,key:`${event.key}-${nextAge}`,category:'Home & renting',age:nextAge,id:`${event.key}-${game.year+1}`,assetId:home.assetId};
}
function makeCarBreakdownEvent(asset,age){
  const condition=asset.condition??70;const premium=/luxury|supercar|exotic/i.test(`${asset.kind} ${asset.name}`)?1.85:/electric|hybrid/i.test((asset.details||[]).map(item=>item.label+' '+item.value).join(' '))?1.35:1;const basis=Math.max(500,asset.purchasePrice||asset.value||8000);const repair=Math.max(180,Math.round(basis*(.004+Math.max(0,75-condition)*.00075)*premium));
  return {key:`car-breakdown-${asset.id}-${age}`,id:`breakdown-${asset.id}-${age}`,age,category:'Vehicle trouble',icon:'🚗',title:`${asset.name} breaks down`,text:`A warning light turns into a breakdown while you are out. The vehicle is at ${condition}% condition. A shop estimates a repair based on its value, type, and wear.`,assetId:asset.id,choices:[{label:`Book a proper repair · ${moneyFmt(repair)}`,detail:'Restore reliability and improve the vehicle condition.',result:`You paid for a proper repair on your ${asset.name}. The mechanic fixed the fault and checked the related systems.`,effects:{money:-repair,assetCondition:{id:asset.id,delta:42}}},{label:`Choose a temporary fix · ${moneyFmt(Math.max(100,Math.round(repair*.42)))}`,detail:'Get back on the road with less work; another repair may be needed.',result:`A mechanic made a temporary repair to your ${asset.name}. It is usable again, but the underlying wear remains.`,effects:{money:-Math.max(100,Math.round(repair*.42)),assetCondition:{id:asset.id,delta:17}}},{label:'Delay the repair',detail:'Keep the cash now, but the car stays unreliable.',result:`You delayed the repair. The ${asset.name} remains unreliable and could break down again.`,effects:{stats:{happiness:-3},assetCondition:{id:asset.id,delta:0}}}]};
}
