const schoolStageForAge=(country,age)=>(schoolSystems[country]||schoolSystems['United States']).find(stage=>age>=stage.start&&age<=stage.end)||null;
function progressSchoolYear(game,nextAge){
  const stage=schoolStageForAge(game.country,nextAge);
  const grade=stage?nextAge-stage.start+1:null;
  const previous=game.schoolRecord||{};
  let story='';
  if(stage&&(!previous.stage||previous.country!==game.country||previous.stage!==stage.name))story=` You started ${stage.name.toLowerCase()}${grade?`, year ${grade}`:''} in ${game.country}.`;
  else if(stage&&previous.grade!==grade)story=` You moved up to year ${grade} of ${stage.name.toLowerCase()}.`;
  let educationLevel=game.educationLevel||0;
  let education=game.education;
  if(nextAge>=18&&educationLevel===0){educationLevel=1;education='High school graduate';story+=` You completed secondary school in ${game.country}.`}
  if(!stage&&nextAge<schoolSystems[game.country]?.[0]?.start)story=' You are getting ready to start school.';
  const lastSchoolAge=(schoolSystems[game.country]||schoolSystems['United States']).slice(-1)[0].end;return {schoolRecord:{country:game.country,stage:stage?.name||(nextAge>lastSchoolAge?'Completed secondary school':'Not school age'),grade,age:nextAge},schoolStory:story,educationLevel,education};
}
