const generateMarket = (catalog, year) => {
  let seed = ((Math.trunc(Number(year) || 1) * 9301 + 49297) >>> 0) || 1;
  const random = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 4294967296; };
  return catalog.map((item) => {
    const priceFactor = 0.91 + random() * 0.18;
    const condition = Math.max(48, Math.min(100, Math.round((item.condition ?? 90) + (random() - 0.5) * 12)));
    const mileage = item.mileage == null ? undefined : Math.max(0, Math.round(item.mileage * (0.92 + random() * 0.16)));
    const horsepower = item.horsepower == null ? undefined : Math.max(60, Math.round(item.horsepower * (0.97 + random() * 0.06)));
    const details = [...(item.details || [])];
    const replaceDetail = (label, value) => {
      const index = details.findIndex((detail) => String(detail).toLowerCase().startsWith(label.toLowerCase()));
      if (index >= 0) details[index] = `${label}: ${value}`;
      else details.push(`${label}: ${value}`);
    };
    replaceDetail('Market year', year);
    if (item.mileage != null) replaceDetail('Mileage', `${mileage.toLocaleString()} mi`);
    if (item.horsepower != null) replaceDetail('Horsepower', `${horsepower} hp`);
    if (item.condition != null) replaceDetail('Condition', `${condition}%`);
    return { ...item, price: Math.max(100, Math.round(item.price * priceFactor / 100) * 100), condition, mileage, horsepower, details, marketYear: year, marketSort: random() };
  }).sort((a, b) => a.marketSort - b.marketSort);
};

