const loanLimitFor = score => score>=740?150000:score>=670?50000:score>=580?12000:score>=500?2500:0;
const loanAprFor = score => score>=740?.075:score>=670?.12:score>=580?.19:score>=500?.29:.45;
const loanMonthlyPayment = (principal,apr,months) => { const rate=apr/12; return rate===0?principal/months:principal*rate/(1-Math.pow(1+rate,-months)); };
const payFromFunds = (g, amount) => { const fromCash=Math.min(g.money,amount);const remainder=amount-fromCash;return {...g,money:g.money-fromCash,bankBalance:Math.max(0,(g.bankBalance||0)-remainder)}; };
export function simulateYearEconomy(input){let cash=input.money,bank=input.bankBalance||0,score=input.creditScore||680;let assets=(input.assets||[]).map(a=>({...a})),loans=(input.loans||[]).map(l=>({...l}));let rentalIncome=0,operatingCosts=0,debtPaid=0,lateCount=0,interestEarned=0;const savingsRate=input.bankAccountType==='Checking'?.0015:.0425;for(let month=0;month<12;month++){const earned=bank*(Math.pow(1+savingsRate,1/12)-1);bank+=earned;interestEarned+=earned;const operatingIncome=assets.reduce((sum,a)=>sum+(a.status==='owned'?a.monthlyIncome||0:0)+monthlyRentalReceipt(a,month),0);bank+=operatingIncome;rentalIncome+=operatingIncome;const dues=assets.reduce((sum,a)=>sum+(a.monthlyCost||0),0);const paid=Math.min(dues,cash+bank);const fromBank=Math.min(bank,paid);bank-=fromBank;cash-=paid-fromBank;operatingCosts+=paid;if(paid<dues){assets=assets.map(a=>({...a,condition:clamp((a.condition||100)-2)}));}loans=loans.map(loan=>{if(loan.status!=='active')return loan;if(loan.studentLoan&&['enrolled','advanced-enrolled'].includes(input.educationStatus)){return {...loan,balance:loan.balance*(1+loan.apr/12)};}const interest=loan.balance*loan.apr/12;const due=Math.min(loan.monthlyPayment,loan.balance+interest);if(cash+bank+0.001>=due){const bankPart=Math.min(bank,due);bank-=bankPart;cash-=due-bankPart;debtPaid+=due;const balance=Math.max(0,loan.balance+interest-due);score=Math.min(850,score+1);return {...loan,balance,monthsPaid:loan.monthsPaid+1,status:balance<1?'paid':'active'};}lateCount++;score=Math.max(300,score-7);const missed=(loan.missedPayments||0)+1;return {...loan,balance:loan.balance+interest+Math.max(10,loan.monthlyPayment*.05),missedPayments:missed,status:'active',defaulted:loan.defaulted||missed>=3};});}assets=assets.map(a=>({...a,value:a.status==='owned'?Math.max(0,Math.round((a.value||0)*(1+(a.depreciation||0)))):a.value,condition:clamp((a.condition||100)-1)}));let transactions=[...(input.transactions||[])];if(interestEarned>0)transactions.unshift({label:'Bank interest',amount:Math.round(interestEarned),year:input.year});if(rentalIncome>0)transactions.unshift({label:'Asset and rental income',amount:rentalIncome,year:input.year});if(operatingCosts>0)transactions.unshift({label:'Property and asset upkeep',amount:-operatingCosts,year:input.year});if(debtPaid>0)transactions.unshift({label:'Loan repayments',amount:-debtPaid,year:input.year});return {...input,money:Math.round(cash),bankBalance:Math.round(bank),creditScore:score,assets,loans,transactions:transactions.slice(0,300),lifetimeIncome:(input.lifetimeIncome||0)+Math.round(interestEarned+rentalIncome),lifetimeSpending:(input.lifetimeSpending||0)+Math.round(operatingCosts+debtPaid),bankTransactions:interestEarned>0?[{label:'Annual interest',amount:Math.round(interestEarned),year:input.year},...(input.bankTransactions||[])]:input.bankTransactions||[],log:lateCount?[{year:input.year,text:`You missed ${lateCount} monthly loan payment${lateCount===1?'':'s'}. Your balance grew and your credit score fell.`,tag:'Credit alert',icon:'⚠️'},...(input.log||[])]:input.log};}
const clamp = n => Math.max(0, Math.min(100, n));
const moneyFmt=formatMoney;
function loadGame() { try { const saved = localStorage.getItem('little-life-save'); if(!saved)return initial;const game={...initial,...JSON.parse(saved)};const family=game.family||initial.family;const allFamily=[...(family.parents||[]),...(family.siblings||[])];const canonicalSurname=allFamily[0]?.name?.trim().split(/\s+/).slice(-1)[0]||randomItem((countryNamePools[game.country]||{last:personLastNames}).last);const normalize=(person,gender)=>({...person,name:`${person.name?.trim().split(/\s+/).slice(0,-1).join(' ')||person.name} ${canonicalSurname}`,gender:person.gender||gender});return {...game,family:{...family,parents:(family.parents||[]).map(person=>normalize(person,(person.relationshipLabel||'').toLowerCase()==='mother'?'Woman':'Man')),siblings:(family.siblings||[]).map(person=>normalize(person,randomItem(['Girl','Boy'])))},pets:game.pets||[]}; } catch { return initial; } }

