      {moreTab==='Themes'&&<><div className="section-intro"><span className="section-art rose"><Palette/></span><div><h3>Choose your mood</h3><p>Your selection applies right away and is saved on this device.</p></div></div><div className="theme-grid">{[{name:'Garden',emoji:'🌿',color:'#698b57'},{name:'Sunshine',emoji:'🌅',color:'linear-gradient(135deg,#ffbd59,#f06a59)'},{name:'Light',emoji:'☀️',color:'#edf1f4'},{name:'Black',emoji:'◐',color:'#050505'}].map(t=><button key={t.name} className={`theme-card ${themeChoice===t.name?'active':''}`} onClick={()=>setThemeChoice(t.name)}><span style={{background:t.color}}>{t.emoji}</span><b>{t.name}</b>{themeChoice===t.name&&<Check size={15}/>}</button>)}</div><div className="premium-themes-heading">PREMIUM THEMES</div>{[{name:'Midnight Bloom',id:'theme-midnight-bloom',emoji:'🌙'},{name:'Starlit Atelier',id:'theme-starlit-atelier',emoji:'🪐'}].map(t=><button key={t.name} className={`owned-theme-row ${themeChoice===t.name?'active':''}`} onClick={()=>ownedThemes.includes(t.name)?setThemeChoice(t.name):setMoreTab('Marketplace')}><span>{t.emoji}</span><b>{t.name}</b><small>{ownedThemes.includes(t.name)?'Select theme':'View in Marketplace'}</small><ArrowRight size={15}/></button>)}</>}
